-- Workspace schema (employee accounts, saved conversations, reviewer grants).
--
-- This schema is deliberately independent from the legacy audit log. It never
-- reads, writes or alters ``events``, ``owners`` or ``export_audits``, and it is
-- applied by ``WorkspaceStore`` at explicit migration version 2 only.
--
-- Run ``workspace_store.WorkspaceStore`` with the dedicated workspace database
-- credential; do not reuse the audit writer/reader roles. PostgreSQL and SQLite
-- share this file and simple parameterised statements. Identifiers are UUID
-- text values generated by the store.

CREATE TABLE IF NOT EXISTS ws_schema_migrations (
    version INTEGER PRIMARY KEY,
    applied_at DOUBLE PRECISION NOT NULL
);

CREATE TABLE IF NOT EXISTS ws_meta (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS ws_departments (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    name_key TEXT NOT NULL UNIQUE,
    created_at DOUBLE PRECISION NOT NULL
);

CREATE TABLE IF NOT EXISTS ws_users (
    id TEXT PRIMARY KEY,
    username TEXT NOT NULL UNIQUE,
    full_name TEXT NOT NULL,
    department_id TEXT NOT NULL REFERENCES ws_departments(id) ON DELETE RESTRICT,
    role TEXT NOT NULL CHECK (role IN ('employee', 'admin')),
    password_hash TEXT NOT NULL,
    disabled INTEGER NOT NULL DEFAULT 0,
    created_at DOUBLE PRECISION NOT NULL
);

CREATE TABLE IF NOT EXISTS ws_sessions (
    token_hash TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES ws_users(id) ON DELETE CASCADE,
    created_at DOUBLE PRECISION NOT NULL,
    expires_at DOUBLE PRECISION NOT NULL,
    revoked INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS ws_review_grants (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES ws_users(id) ON DELETE CASCADE,
    scope TEXT NOT NULL CHECK (scope IN ('department', 'global')),
    scope_key TEXT NOT NULL,
    department_id TEXT REFERENCES ws_departments(id) ON DELETE CASCADE,
    created_by TEXT NOT NULL REFERENCES ws_users(id) ON DELETE RESTRICT,
    created_at DOUBLE PRECISION NOT NULL,
    UNIQUE (user_id, scope_key)
);

CREATE TABLE IF NOT EXISTS ws_conversations (
    id TEXT PRIMARY KEY,
    owner_id TEXT NOT NULL REFERENCES ws_users(id) ON DELETE CASCADE,
    department_id TEXT NOT NULL REFERENCES ws_departments(id) ON DELETE RESTRICT,
    title TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'idle' CHECK (status IN ('idle', 'pending', 'appending')),
    lease_hash TEXT,
    lease_expires_at DOUBLE PRECISION,
    version INTEGER NOT NULL DEFAULT 0,
    created_at DOUBLE PRECISION NOT NULL,
    updated_at DOUBLE PRECISION NOT NULL
);

CREATE TABLE IF NOT EXISTS ws_messages (
    id TEXT PRIMARY KEY,
    conversation_id TEXT NOT NULL REFERENCES ws_conversations(id) ON DELETE CASCADE,
    role TEXT NOT NULL CHECK (role IN ('user', 'assistant')),
    position INTEGER NOT NULL,
    ciphertext TEXT NOT NULL,
    -- A failed/blocked user turn is retained with metadata but never enters
    -- the next Gateway context. Only a delivered (masked) answer is 'allowed'.
    outcome TEXT NOT NULL DEFAULT 'allowed'
        CHECK (outcome IN ('allowed', 'blocked', 'failed')),
    request_id TEXT,
    error_code TEXT,
    created_at DOUBLE PRECISION NOT NULL,
    UNIQUE (conversation_id, position)
);

CREATE TABLE IF NOT EXISTS ws_access_log (
    id TEXT PRIMARY KEY,
    actor_id TEXT NOT NULL,
    action TEXT NOT NULL,
    conversation_id TEXT,
    department_id TEXT,
    created_at DOUBLE PRECISION NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_ws_users_department ON ws_users(department_id);
CREATE INDEX IF NOT EXISTS idx_ws_sessions_user ON ws_sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_ws_review_grants_user ON ws_review_grants(user_id);
CREATE INDEX IF NOT EXISTS idx_ws_conversations_owner
    ON ws_conversations(owner_id, created_at, id);
CREATE INDEX IF NOT EXISTS idx_ws_conversations_department
    ON ws_conversations(department_id, created_at, id);
CREATE INDEX IF NOT EXISTS idx_ws_messages_conversation
    ON ws_messages(conversation_id, position);
CREATE INDEX IF NOT EXISTS idx_ws_access_log_created ON ws_access_log(created_at, id);
